const CAT_ICONS={Food:'🍜','Social Life':'🎉',Transportation:'🚗',Household:'🏠',Apparel:'👕',Beauty:'💄',Health:'❤️',Education:'📚',Gift:'🎁',Pet:'🐾','Self-development':'🌱',Internet:'🌐',Electricity:'⚡',Water:'💧',Mobile:'📱','Life Insurance':'🛡️','Health Insurance':'🏥','City Garbage':'🗑️',Gas:'⛽',Paycheck:'💼',Business:'🏢','Side Hustle':'💡',Dividends:'📈','Interest Income':'💰',Commission:'🤝',Other:'📦'};
