const state={user:null,access:null,page:'dashboard',filterType:'month',filterPeriod:new Date().toISOString().slice(0,7),data:{transactions:[],accounts:[],budgets:[],savings:[],investments:[],saving_contributions:[],bills:[],assets:[]},privacy:false,lang:localStorage.getItem('lamtrack-lang')||'id'};
const I18N={id:{dashboard:'Dashboard',transactions:'Transaksi',budget:'Budget',savings:'Tabungan',investments:'Investasi',accounts:'Akun Finansial',analytics:'Analytics & Laporan',assistant:'Asisten LamTrack',bills:'Tagihan',settings:'Pengaturan',dashSub:'Ringkasan keuanganmu',billSub:'Kelola tagihan dan pembayaran rutin',analyticsSub:'Lihat semua grafik dan kebiasaan keuangan',settingsSub:'Profil, tampilan, bahasa, keamanan dan privasi',notification:'Notifikasi',noNotifications:'Tidak ada peringatan. Keuanganmu sedang tenang.',language:'Bahasa',indonesian:'Indonesia',english:'English',upcomingBills:'Tagihan mendatang',addBill:'Tambah tagihan',editBill:'Edit tagihan',deleteBill:'Hapus tagihan',provider:'Penyedia',billName:'Nama tagihan',dueDate:'Jatuh tempo',frequency:'Frekuensi',monthly:'Bulanan',weekly:'Mingguan',quarterly:'Triwulan',yearly:'Tahunan',amount:'Nominal',active:'Aktif',autopay:'Auto bayar',notes:'Catatan',save:'Simpan',cancel:'Batal',exportPdf:'Export PDF',financialEvaluation:'Evaluasi keuangan',warning:'Peringatan',dontOverspend:'Jangan boros',nearBudget:'Mendekati budget',overBudget:'Budget terlampaui',daysLeft:'hari lagi',today:'Hari ini',overdue:'Terlambat',theme:'Tampilan',white:'Putih',dark:'Gelap'},en:{dashboard:'Dashboard',transactions:'Transactions',budget:'Budget',savings:'Savings',investments:'Investments',accounts:'Financial Accounts',analytics:'Analytics & Reports',assistant:'LamTrack Assistant',bills:'Bills',settings:'Settings',dashSub:'Your financial overview',billSub:'Manage bills and recurring payments',analyticsSub:'See charts and financial habits',settingsSub:'Profile, appearance, language, security and privacy',notification:'Notifications',noNotifications:'No warnings. Your finances are calm.',language:'Language',indonesian:'Indonesian',english:'English',upcomingBills:'Upcoming bills',addBill:'Add bill',editBill:'Edit bill',deleteBill:'Delete bill',provider:'Provider',billName:'Bill name',dueDate:'Due date',frequency:'Frequency',monthly:'Monthly',weekly:'Weekly',quarterly:'Quarterly',yearly:'Yearly',amount:'Amount',active:'Active',autopay:'Auto pay',notes:'Notes',save:'Save',cancel:'Cancel',exportPdf:'Export PDF',financialEvaluation:'Financial evaluation',warning:'Warning',dontOverspend:'Watch your spending',nearBudget:'Budget nearly reached',overBudget:'Budget exceeded',daysLeft:'days left',today:'Today',overdue:'Overdue',theme:'Appearance',white:'Light',dark:'Dark'}};
function t(k){return (I18N[state.lang]||I18N.id)[k]||k}function setLang(lang){state.lang=lang;localStorage.setItem('lamtrack-lang',lang);document.documentElement.lang=lang==='en'?'en':'id';const info=titleInfo();$('#page-title').textContent=info[0];$('#page-subtitle').textContent=info[1];applyLanguage();render();toast(lang==='en'?'English enabled 🇬🇧':'Bahasa Indonesia aktif 🇮🇩')}function applyLanguage(){document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(I18N[state.lang]?.[k])el.textContent=I18N[state.lang][k]})}
const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0);const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const today=()=>new Date().toISOString().slice(0,10);const fmtDate=d=>d?new Date(d+'T00:00:00').toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}):'-';const pct=(a,b)=>b?Math.min(100,Math.round(a/b*100)):0;
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className='toast show '+(error?'error':'');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.className='toast',3200)}
let __confirmResolver=null;
function openModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').classList.remove('hidden');document.body.classList.add('modal-open');setTimeout(()=>$('#modal-body input, #modal-body select, #modal-body textarea')?.focus(),40)}
function closeModal(result=false){if(__confirmResolver){const r=__confirmResolver;__confirmResolver=null;r(result)}$('#modal').classList.add('hidden');document.body.classList.remove('modal-open')}
function confirmModal({title='Konfirmasi',message='Apakah kamu yakin?',detail='',confirmText='Hapus',danger=true}){return new Promise(resolve=>{__confirmResolver=resolve;openModal(title,`<div class="confirm-modal"><div class="confirm-icon ${danger?'danger':'safe'}">${danger?'🗑️':'🔔'}</div><h4>${esc(title)}</h4><p>${esc(message)}</p>${detail?`<small>${esc(detail)}</small>`:''}<div class="modal-actions"><button class="secondary" type="button" data-confirm-choice="cancel">Batal</button><button class="${danger?'danger-button':'primary'}" type="button" data-confirm-choice="ok">${esc(confirmText)}</button></div></div>`)})}
function emailSentModal(email){openModal('Email berhasil dikirim',`<div class="email-success-modal"><div class="success-orb">✉️</div><h4>Cek inbox kamu</h4><p>Link reset password sudah diminta untuk akun:</p><div class="email-chip">${esc(email)}</div><div class="email-steps"><div><b>01</b><span>Buka inbox email</span></div><div><b>02</b><span>Cari email dari Supabase / LamTrack</span></div><div><b>03</b><span>Klik link lalu buat password baru</span></div></div><div class="modal-note">Tidak menemukan email? Periksa folder Spam atau Promosi. Link reset juga memiliki masa berlaku.</div><div class="modal-actions"><button class="primary full" type="button" data-close-modal>Mengerti, tutup</button></div></div>`)}
function forgotPasswordModal(){if(!sb)return toast('Hubungkan Supabase dulu',true);const preset=$('#login-email')?.value.trim()||'';openModal('Lupa password?',`<div class="auth-modern-modal"><div class="modern-modal-icon">🔐</div><h4>Reset akses LamTrack</h4><p>Masukkan email akunmu. Kami akan mengirim link untuk membuat password baru.</p><form id="forgot-password-form" class="modal-form"><label>Email akun<input id="forgot-email" name="email" type="email" autocomplete="email" value="${esc(preset)}" required placeholder="nama@email.com"></label><div class="security-hint">🛡️ Link reset hanya dikirim melalui email dan tidak pernah menampilkan passwordmu.</div><div class="modal-actions"><button class="secondary" type="button" data-close-modal>Batal</button><button class="primary" type="submit" id="forgot-submit">Kirim link reset</button></div></form></div>`);$('#forgot-password-form').onsubmit=async e=>{e.preventDefault();const email=new FormData(e.currentTarget).get('email').toString().trim();const btn=$('#forgot-submit');if(!email)return;btn.disabled=true;btn.textContent='Mengirim...';const redirectTo=`${location.origin}${location.pathname}?reset=1`;const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo});if(error){btn.disabled=false;btn.textContent='Kirim link reset';return toast(error.message,true)}emailSentModal(email)} }
function passwordModal(context='settings'){if(!sb)return toast('Hubungkan Supabase dulu',true);openModal(context==='recovery'?'Buat password baru':'Ganti password',`<div class="auth-modern-modal"><div class="modern-modal-icon">🔑</div><h4>${context==='recovery'?'Amankan kembali akunmu':'Perbarui password akunmu'}</h4><p>${context==='recovery'?'Buat password baru untuk menyelesaikan proses pemulihan akun.':'Gunakan password yang kuat dan berbeda dari password akun lain.'}</p><form id="password-form" class="modal-form"><label>Password baru<div class="password-wrap modern-password"><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="6" required placeholder="Minimal 6 karakter"><button type="button" class="password-eye" data-toggle-password="new-password">👁️</button></div></label><div class="password-strength"><div class="strength-track"><span id="password-strength-bar"></span></div><small id="password-strength-text">Masukkan password</small></div><label>Konfirmasi password<div class="password-wrap modern-password"><input id="confirm-password" name="confirm_password" type="password" autocomplete="new-password" minlength="6" required placeholder="Ulangi password baru"><button type="button" class="password-eye" data-toggle-password="confirm-password">👁️</button></div></label><div class="security-hint">🛡️ Minimal 6 karakter. Gunakan kombinasi huruf, angka, dan simbol jika memungkinkan.</div><div class="modal-actions"><button class="secondary" type="button" data-close-modal>Batal</button><button class="primary" type="submit" id="password-submit">Simpan password</button></div></form></div>`);const form=$('#password-form'),pass=$('#new-password'),confirm=$('#confirm-password'),bar=$('#password-strength-bar'),text=$('#password-strength-text');const updateStrength=()=>{const v=pass.value;let score=0;if(v.length>=6)score++;if(v.length>=10)score++;if(/[A-Z]/.test(v)&&/[a-z]/.test(v))score++;if(/\d/.test(v))score++;if(/[^A-Za-z0-9]/.test(v))score++;const pct=Math.min(100,score/5*100);bar.style.width=pct+'%';text.textContent=!v?'Masukkan password':score<=2?'Kekuatan: lemah':score<=3?'Kekuatan: cukup':'Kekuatan: kuat'};pass.addEventListener('input',updateStrength);form.onsubmit=async e=>{e.preventDefault();const p=pass.value,c=confirm.value;if(p.length<6)return toast('Password minimal 6 karakter',true);if(p!==c)return toast('Konfirmasi password belum sama',true);const btn=$('#password-submit');btn.disabled=true;btn.textContent='Menyimpan...';const {data,error}=await sb.auth.updateUser({password:p});if(error){btn.disabled=false;btn.textContent='Simpan password';return toast(error.message,true)}closeModal();toast('Password berhasil diubah 🔐');if(context==='recovery'){clearRecoveryUrl();}}}

function showPremiumAI(feature='AI'){openModal(`✨ ${feature} · Premium`, `<div class="premium-coming-modal"><div class="premium-coming-orb">🤖</div><span class="premium-coming-badge">COMING SOON · PREMIUM</span><h4>AI akan hadir di LamTrack</h4><p>Fitur <b>${esc(feature)}</b> sedang kami siapkan sebagai Premium. Semua fitur inti LamTrack tetap bisa digunakan tanpa biaya AI.</p><div class="premium-coming-list"><div>📸 <span>Scan struk otomatis</span><b>Premium</b></div><div>🧠 <span>AI Advisor keuangan</span><b>Premium</b></div><div>🌐 <span>Insight informasi terkini</span><b>Premium</b></div></div><div class="modal-note">💚 Simpan LamTrack di Home Screen sekarang. Saat budget AI sudah siap, fitur Premium tinggal diaktifkan.</div><div class="modal-actions"><button class="primary full" type="button" data-close-modal>Mengerti</button></div></div>`)}
function askAdvisor(){showPremiumAI('AI Advisor')}
function installLamTrack(){if(deferredInstallPrompt){deferredInstallPrompt.prompt();deferredInstallPrompt.userChoice.then(()=>{deferredInstallPrompt=null;render()});return}toast('Gunakan menu Install / Add to Home Screen di browser untuk memasang LamTrack.')}

function showAuth(which='login'){document.querySelectorAll('.auth-tab').forEach(x=>x.classList.toggle('active',x.dataset.auth===which));$('#login-form').classList.toggle('hidden',which!=='login');$('#register-form').classList.toggle('hidden',which!=='register')}
function currentName(){return state.user?.user_metadata?.full_name||state.user?.email?.split('@')[0]||'Teman'}function profileInitials(){return currentName().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()||'U'}function val(n){return state.privacy?'••••••••':money(n)}
function txFiltered(){const tx=state.data.transactions;if(state.filterType==='month')return tx.filter(t=>String(t.date).slice(0,7)===state.filterPeriod);if(state.filterType==='year')return tx.filter(t=>String(t.date).slice(0,4)===state.filterPeriod);return tx}
function filterLabel(){return state.filterType==='month'?new Date(state.filterPeriod+'-01T00:00:00').toLocaleDateString('id-ID',{month:'long',year:'numeric'}):state.filterType==='year'?state.filterPeriod:'Semua waktu'}
function populateFilters(){
  const p=$('#filter-period'); if(!p)return; p.innerHTML='';
  const now=new Date(); now.setDate(1); const currentMonth=now.toISOString().slice(0,7); const currentYear=now.getFullYear();
  if(state.filterType==='month'){
    const past=document.createElement('optgroup'); past.label='Bulan sebelumnya';
    for(let i=1;i<=36;i++){const d=new Date(now);d.setMonth(now.getMonth()-i);const v=d.toISOString().slice(0,7);past.appendChild(new Option(d.toLocaleDateString('id-ID',{month:'long',year:'numeric'}),v,v===state.filterPeriod,v===state.filterPeriod));}
    p.appendChild(past);
    const current=document.createElement('optgroup'); current.label='Bulan berjalan';
    current.appendChild(new Option(now.toLocaleDateString('id-ID',{month:'long',year:'numeric'}),currentMonth,currentMonth===state.filterPeriod,currentMonth===state.filterPeriod)); p.appendChild(current);
    const future=document.createElement('optgroup'); future.label='Bulan mendatang';
    for(let i=1;i<=36;i++){const d=new Date(now);d.setMonth(now.getMonth()+i);const v=d.toISOString().slice(0,7);future.appendChild(new Option(d.toLocaleDateString('id-ID',{month:'long',year:'numeric'}),v,v===state.filterPeriod,v===state.filterPeriod));}
    p.appendChild(future);
  }else if(state.filterType==='year'){
    const past=document.createElement('optgroup'); past.label='Tahun sebelumnya';
    for(let i=1;i<=10;i++){const v=String(currentYear-i);past.appendChild(new Option(v,v,v===state.filterPeriod,v===state.filterPeriod));} p.appendChild(past);
    const current=document.createElement('optgroup'); current.label='Tahun berjalan';
    current.appendChild(new Option(String(currentYear),String(currentYear),String(currentYear)===state.filterPeriod,String(currentYear)===state.filterPeriod)); p.appendChild(current);
    const future=document.createElement('optgroup'); future.label='Tahun mendatang';
    for(let i=1;i<=15;i++){const v=String(currentYear+i);future.appendChild(new Option(v,v,v===state.filterPeriod,v===state.filterPeriod));} p.appendChild(future);
  }else p.add(new Option('Semua bulan & tahun','all',true,true));
}
function titleInfo(){return{dashboard:[t('dashboard'),t('dashSub')],transactions:[t('transactions'),state.lang==='en'?'Track and manage income & expenses':'Catat dan kelola semua pemasukan & pengeluaran'],budget:[t('budget'),state.lang==='en'?'Set spending limits':'Atur batas pengeluaran'],savings:[t('savings'),state.lang==='en'?'Savings goals and contributions':'Target dan kontribusi tabungan'],investments:[t('investments'),state.lang==='en'?'Track your assets and returns':'Pantau aset dan perkembangan investasi'],accounts:[t('accounts'),state.lang==='en'?'Manage bank, e-wallet and cash':'Kelola bank, e-wallet dan cash'],analytics:[t('analytics'),t('analyticsSub')],assistant:[t('assistant'),state.lang==='en'?'AI for recording and understanding your finances':'AI untuk mencatat dan memahami keuanganmu'],assets:[state.lang==='en'?'Assets':'Aset',state.lang==='en'?'Track your house, land, cars and other real assets':'Pantau rumah, tanah, mobil, motor, dan aset nyata lainnya'],admin:[state.lang==='en'?'Admin Center':'Pusat Admin',state.lang==='en'?'Manage users and access':'Kelola pengguna dan akses'],bills:[t('bills'),t('billSub')],settings:[t('settings'),t('settingsSub')]}[state.page]}
function setPage(p){state.page=p;const t=titleInfo();$('#page-title').textContent=t[0];$('#page-subtitle').textContent=t[1];document.querySelectorAll('.nav-item[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));document.querySelectorAll('.profile-nav[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('.sidebar').classList.remove('open');render()}
async function getAccessStatus(){if(!sb||!state.user)return null;const {data,error}=await sb.rpc('get_my_access');if(error){console.warn('get_my_access',error.message);return {status:'pending',role:'user',plan:'free'};}const a=Array.isArray(data)?(data[0]||null):(data||null);if(a&&a.status==='approved'&&a.expires_at&&new Date(a.expires_at).getTime()<=Date.now()&&!['owner','super_admin'].includes(a.role))a.status='expired';return a}
function updateAdminNav(){const isAdmin=['owner','super_admin'].includes(state.access?.role);let nav=document.querySelector('.admin-nav');if(isAdmin&&!nav){nav=document.createElement('button');nav.className='nav-item admin-nav';nav.dataset.page='admin';nav.innerHTML='🛡️ <span>Pusat Admin</span><b class="nav-pill admin-pill">ADMIN</b>';document.querySelector('.sidebar nav')?.appendChild(nav)}if(nav)nav.classList.toggle('hidden',!isAdmin)}
function renderAccessGate(){const a=state.access||{},status=a.status||'pending';const title=status==='rejected'?'Permintaan akses ditolak':status==='suspended'?'Akses ditangguhkan':status==='expired'?'Akses telah berakhir':status==='payment_pending'?'Menunggu verifikasi pembayaran':'Menunggu persetujuan admin';const text=status==='rejected'?'Admin belum menyetujui akses akun ini. Silakan hubungi admin LamTrack.':status==='suspended'?'Akses akun sedang ditangguhkan oleh admin.':status==='expired'?`Masa berlaku paket ${esc(a.plan||'premium')} telah berakhir. Hubungi admin untuk perpanjangan.`:status==='payment_pending'?'Paket Premium/Pro membutuhkan pembayaran yang sudah diverifikasi admin sebelum akses diaktifkan.':'Akunmu sudah terdaftar. Setelah pembayaran dan verifikasi admin selesai, akses akan diaktifkan.';const icon=status==='pending'?'⏳':status==='expired'?'⌛':status==='payment_pending'?'💳':status==='suspended'?'🔒':'⛔';$('#content').innerHTML=`<section class="access-gate-page"><div class="access-gate-orb">${icon}</div><span class="premium-coming-badge">LAMTRACK ACCESS · ${status.toUpperCase().replace('_',' ')}</span><h1>${title}</h1><p>${text}</p><div class="access-steps"><div><b>01</b><span>Daftar & verifikasi email</span></div><div><b>02</b><span>Admin memverifikasi pembayaran</span></div><div><b>03</b><span>Akses LamTrack diaktifkan</span></div></div><div class="access-meta"><span>Status</span><strong>${esc(status.replace('_',' '))}</strong><span>Paket</span><strong>${esc(a.plan||'free')}</strong>${a.expires_at?`<span>Berlaku</span><strong>${fmtDate(String(a.expires_at).slice(0,10))}</strong>`:''}</div><div class="access-actions"><button class="primary" data-action="profile-menu">👤 Profil</button><button class="secondary" data-action="logout-access">Keluar</button></div></section>`}
function adminStatusLabel(v){return ({pending:'PENDING',approved:'APPROVED',suspended:'SUSPENDED',rejected:'REJECTED',expired:'EXPIRED'}[v]||String(v||'PENDING')).toUpperCase()}
function adminPaymentLabel(v){return ({unpaid:'Belum bayar',pending:'Menunggu verifikasi',paid:'Sudah bayar',refunded:'Refund'}[v]||'Belum bayar')}
function adminManageModal(u){
  const plan=u.plan||'free', payment=u.payment_status||'unpaid', exp=u.expires_at?String(u.expires_at).slice(0,10):'';
  openModal(`Kelola akses · ${u.full_name||'User'}`,`<form id="admin-commercial-form" class="modal-form admin-commercial-form" data-user-id="${u.user_id}">
    <div class="admin-user-preview"><div class="sidebar-avatar">${esc((u.full_name||'U').slice(0,1).toUpperCase())}</div><div><b>${esc(u.full_name||'User')}</b><small>${esc(u.email||'')}</small></div><span class="access-status ${esc(u.status||'pending')}">${adminStatusLabel(u.status)}</span></div>
    <div class="form-grid">
      <label>Status akses<select name="status"><option value="pending" ${u.status==='pending'?'selected':''}>Pending</option><option value="approved" ${u.status==='approved'?'selected':''}>Approved / Aktif</option><option value="suspended" ${u.status==='suspended'?'selected':''}>Suspended</option><option value="rejected" ${u.status==='rejected'?'selected':''}>Rejected</option></select></label>
      <label>Paket<select name="plan"><option value="free" ${plan==='free'?'selected':''}>Free</option><option value="premium" ${plan==='premium'?'selected':''}>Premium</option><option value="pro" ${plan==='pro'?'selected':''}>Pro</option>${u.role==='owner'?'<option value="owner" selected>Owner</option>':''}</select></label>
      <label>Status pembayaran<select name="payment_status"><option value="unpaid" ${payment==='unpaid'?'selected':''}>Belum bayar</option><option value="pending" ${payment==='pending'?'selected':''}>Menunggu verifikasi</option><option value="paid" ${payment==='paid'?'selected':''}>Sudah bayar</option><option value="refunded" ${payment==='refunded'?'selected':''}>Refund</option></select></label>
      <label>Nominal pembayaran<input name="payment_amount" type="number" min="0" step="1000" value="${Number(u.payment_amount||0)}" placeholder="0"></label>
      <label>Berlaku sampai<input name="expires_at" type="date" value="${esc(exp)}"><small class="muted">Kosongkan untuk tanpa batas. Owner/Super Admin otomatis tanpa batas.</small></label>
      <label>Referensi pembayaran<input name="payment_reference" type="text" value="${esc(u.payment_reference||'')}" placeholder="Contoh: INV-2026-001"></label>
      <label class="full-col">Catatan pembayaran<textarea name="payment_notes" rows="3" placeholder="Contoh: Transfer sudah diverifikasi.">${esc(u.payment_notes||'')}</textarea></label>
    </div>
    <div class="admin-commercial-hint">🔐 Premium/Pro hanya dapat diaktifkan setelah pembayaran <b>Sudah bayar</b>. Expiry akan mengunci akses user biasa setelah tanggal berakhir.</div>
    <div class="modal-actions"><button type="button" class="secondary" data-close-modal>Batal</button><button type="submit" class="primary">Simpan & terapkan</button></div>
  </form>`);
  const f=$('#admin-commercial-form');
  f.onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(f));const status=o.status,plan=o.plan,payment=o.payment_status;const expValue=o.expires_at?`${o.expires_at}T23:59:59`:null;const amount=Math.max(0,Number(o.payment_amount||0));if((plan==='premium'||plan==='pro')&&status==='approved'&&payment!=='paid')return toast('Premium/Pro memerlukan pembayaran yang sudah diverifikasi.',true);const btn=f.querySelector('button[type="submit"]');btn.disabled=true;btn.textContent='Menyimpan...';const {error}=await sb.rpc('admin_set_commercial',{target_user_id:u.user_id,new_status:status,new_plan:plan,new_expires_at:expValue,new_payment_status:payment,new_payment_amount:amount,new_payment_reference:o.payment_reference||null,new_payment_notes:o.payment_notes||null});if(error){btn.disabled=false;btn.textContent='Simpan & terapkan';return toast(error.message,true)}closeModal();toast('Akses komersial diperbarui ✓');await loadAdminUsers()}
}
function renderAdmin(){if(!['owner','super_admin'].includes(state.access?.role))return renderAccessGate(),'';return `<section class="admin-page"><div class="admin-hero"><div><span class="eyebrow">LAMTRACK CONTROL CENTER</span><h1>Pusat Admin 🛡️</h1><p>Kelola pengguna, verifikasi pembayaran, paket, masa berlaku, dan monitoring.</p></div><div class="admin-orb">🛡️</div></div><div id="admin-users" class="card admin-users-card"><div class="section-title"><div><h3>👥 Pengguna & akses</h3><span class="section-hint">Verifikasi pembayaran sebelum mengaktifkan Premium/Pro.</span></div><button class="secondary" data-action="admin-refresh">↻ Refresh</button></div><div class="admin-loading">Memuat pengguna...</div></div></section>`}
