function isRecoveryRedirect(){const q=new URLSearchParams(location.search);const h=location.hash||'';return q.get('reset')==='1'||h.includes('type=recovery')||h.includes('access_token=')||h.includes('code=')}function clearRecoveryUrl(){history.replaceState({},document.title,location.pathname)}async function boot(){if(!isConfigured){toast('Hubungkan Supabase dulu di js/config.js',true);return}let recoveryPending=isRecoveryRedirect(),recoveryShown=false;const showRecovery=()=>{if(recoveryShown)return;recoveryShown=true;setTimeout(()=>passwordModal('recovery'),220)};sb.auth.onAuthStateChange(async(event,s)=>{if(event==='PASSWORD_RECOVERY')recoveryPending=true;if(event==='INITIAL_SESSION')return;if(s){await startApp(s.user);if(event==='PASSWORD_RECOVERY'||recoveryPending)showRecovery()}else{$('#auth-page').classList.remove('hidden');$('#app').classList.add('hidden')}});const {data:{session}}=await sb.auth.getSession();if(session){await startApp(session.user);if(recoveryPending)showRecovery()}}
