function doughnut(parts,total,label='Total'){const size=210,c=105,r=72,inner=43,circ=2*Math.PI*r;let offset=0;const seg=parts.filter(x=>x.value>0).map(x=>{const len=x.value/total*circ;const s=`<circle cx="${c}" cy="${c}" r="${r}" fill="none" stroke="${x.color}" stroke-width="29" stroke-dasharray="${len} ${circ-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 ${c} ${c})"/>`;offset+=len;return s}).join('');return `<div class="donut-box"><svg viewBox="0 0 ${size} ${size}" class="donut"><circle cx="${c}" cy="${c}" r="${r}" fill="none" stroke="#edf1e9" stroke-width="29"/>${seg}<circle cx="${c}" cy="${c}" r="${inner}" fill="white"/><text x="${c}" y="100" text-anchor="middle" class="donut-number">${esc(money(total))}</text><text x="${c}" y="119" text-anchor="middle" class="donut-label">${esc(label)}</text></svg></div>`}
function pieLegend(parts,total){return `<div class="pie-legend">${parts.filter(x=>x.value>0).map(x=>`<div><span class="legend-dot" style="background:${x.color}"></span><span>${esc(x.label)}</span><b>${money(x.value)}</b><small>${pct(x.value,total)}%</small></div>`).join('')||'<div class="empty-mini">Belum ada data</div>'}</div>`}
function bars7(tx){const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);days.push(d.toISOString().slice(0,10))}const vals=days.map(d=>tx.filter(t=>t.type==='expense'&&t.date===d).reduce((a,x)=>a+Number(x.amount),0));const max=Math.max(...vals,1),peak=Math.max(...vals),peakDay=days[vals.indexOf(peak)];return `<div class="bar7">${vals.map((v,i)=>`<div class="bar7-col"><div class="bar7-value">${v?money(v).replace('Rp',''):''}</div><div class="bar7-bar" style="height:${Math.max(6,v/max*145)}px"></div><b>${new Date(days[i]+'T00:00:00').toLocaleDateString('id-ID',{weekday:'short'}).slice(0,3)}</b></div>`).join('')}</div><div class="spend-alert">🔥 Hari paling boros: <b>${peak?new Date(peakDay+'T00:00:00').toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long'}):'-'}</b> ${peak?`dengan ${money(peak)}`:'belum ada pengeluaran'}</div>`}
function accountBalance(account){
  if(!account) return 0;
  const base=Number(account.balance||0);
  const net=state.data.transactions.filter(t=>String(t.account_id)===String(account.id)).reduce((sum,t)=>sum+(t.type==='income'?1:-1)*Number(t.amount||0),0);
  return base+net;
}
function totalAccountBalance(){return state.data.accounts.reduce((sum,a)=>sum+accountBalance(a),0)}
function budgetSpent(b, mode='selected'){
  const freq=b.frequency||'monthly';
  let start,end;
  if(freq==='weekly'){
    const base=new Date(); const day=base.getDay(); const diff=(day+6)%7; start=new Date(base); start.setDate(base.getDate()-diff); end=new Date(start); end.setDate(start.getDate()+6);
  }else if(freq==='monthly'){
    const key=state.filterType==='month'?state.filterPeriod:new Date().toISOString().slice(0,7); start=new Date(key+'-01T00:00:00'); end=new Date(start); end.setMonth(start.getMonth()+1); end.setDate(0);
  }else if(freq==='quarterly'){
    const key=state.filterType==='month'?state.filterPeriod:new Date().toISOString().slice(0,7); const d=new Date(key+'-01T00:00:00'); const q=Math.floor(d.getMonth()/3)*3; start=new Date(d.getFullYear(),q,1); end=new Date(d.getFullYear(),q+3,0);
  }else if(freq==='yearly'){
    const y=state.filterType==='year'?Number(state.filterPeriod):new Date().getFullYear(); start=new Date(y,0,1); end=new Date(y,11,31);
  }else{
    start=new Date((b.start_date||today())+'T00:00:00'); end=new Date((b.end_date||b.start_date||today())+'T00:00:00');
  }
  const a=start.getTime(),z=end.getTime()+86400000;
  return state.data.transactions.filter(t=>t.type==='expense'&&t.category===b.category).filter(t=>{const d=new Date(String(t.date)+'T00:00:00').getTime();return d>=a&&d<z}).reduce((sum,t)=>sum+Number(t.amount||0),0);
}
function billDays(b){const d=new Date(String(b.due_date)+'T00:00:00'),n=new Date();n.setHours(0,0,0,0);return Math.ceil((d-n)/86400000)}
function upcomingBills(){return state.data.bills.slice().filter(b=>b.is_active!==false).sort((a,b)=>String(a.due_date).localeCompare(String(b.due_date))).slice(0,6)}
function billStatus(b){const d=billDays(b);return d<0?`<span class="bill-status overdue">${t('overdue')}</span>`:d===0?`<span class="bill-status today">${t('today')}</span>`:`<span class="bill-status">${d} ${t('daysLeft')}</span>`}
function billFrequencyLabel(f){return t(f||'monthly')}

function calendarExpense(monthKey){
  const [y,m]=monthKey.split('-').map(Number),first=new Date(y,m-1,1),last=new Date(y,m,0),offset=(first.getDay()+6)%7,days=[];
  for(let i=0;i<offset;i++)days.push('<div class="cal-day cal-empty"></div>');
  for(let d=1;d<=last.getDate();d++){
    const key=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const total=state.data.transactions.filter(t=>t.type==='expense'&&t.date===key).reduce((a,x)=>a+Number(x.amount||0),0);
    days.push(`<div class="cal-day ${total?'has-expense':''}"><b>${d}</b>${total?`<small>-${money(total).replace('Rp','')}</small>`:''}</div>`);
  }
  return `<div class="calendar-head"><span>Sen</span><span>Sel</span><span>Rab</span><span>Kam</span><span>Jum</span><span>Sab</span><span>Min</span></div><div class="calendar-grid">${days.join('')}</div>`;
}
function healthScore(tx,balance){
  const income=tx.filter(t=>t.type==='income').reduce((a,x)=>a+Number(x.amount),0),expense=tx.filter(t=>t.type==='expense').reduce((a,x)=>a+Number(x.amount),0);
  const savingRate=income?Math.max(0,Math.min(1,(income-expense)/income)):0;
  const budgets=state.data.budgets.filter(budgetMatches); let discipline=1;
  if(budgets.length){const ratios=budgets.map(b=>{const used=budgetSpent(b);return Number(b.amount)?Math.min(1,used/Number(b.amount)):0});discipline=ratios.reduce((a,x)=>a+x,0)/ratios.length;}
  const monthlyExp=state.data.transactions.filter(t=>t.type==='expense').reduce((a,x)=>a+Number(x.amount),0)/Math.max(1,new Set(state.data.transactions.map(t=>String(t.date).slice(0,7))).size);
  const runway=monthlyExp?Math.min(1,Math.max(0,balance/monthlyExp/6)):0;
  const score=Math.round(savingRate*45+discipline*25+runway*30);
  return {score,savingRate:Math.round(savingRate*100),discipline:Math.round(discipline*100),runway:Math.round(runway*100)};
}
function getFinancePlan(){
  try{const p=JSON.parse(localStorage.getItem('lamtrack-finance-plan')||'{}');return Object.assign({needs:50,saving:20,investment:15,lifestyle:10,emergency:5},p)}catch{return {needs:50,saving:20,investment:15,lifestyle:10,emergency:5}}
}
function financePlanTotal(p=getFinancePlan()){return Object.values(p).reduce((a,v)=>a+Number(v||0),0)}
function saveFinancePlan(p){if(financePlanTotal(p)!==100)return false;localStorage.setItem('lamtrack-finance-plan',JSON.stringify(p));return true}
function financePlanModal(){const p=getFinancePlan();openModal('⚙️ Atur rekomendasi keuangan',`<form id="finance-plan-form" class="modal-form"><p class="muted">Atur pembagian persentase sesuai gaya keuanganmu. LamTrack akan otomatis menghitung nominal berdasarkan pemasukan periode yang sedang dipilih.</p><div class="form-grid"><label>🏠 Kebutuhan (%)<input name="needs" type="number" min="0" max="100" value="${p.needs}" required></label><label>💰 Tabungan (%)<input name="saving" type="number" min="0" max="100" value="${p.saving}" required></label><label>📈 Investasi (%)<input name="investment" type="number" min="0" max="100" value="${p.investment}" required></label><label>🎉 Lifestyle (%)<input name="lifestyle" type="number" min="0" max="100" value="${p.lifestyle}" required></label><label>🛡️ Dana darurat (%)<input name="emergency" type="number" min="0" max="100" value="${p.emergency}" required></label><div class="card plan-total-preview" id="plan-total-preview"><b>Total: ${financePlanTotal(p)}%</b><small>Harus tepat 100%</small></div></div><div class="modal-actions"><button type="button" class="secondary" data-close-modal>Batal</button><button class="primary" type="submit">Simpan pengaturan</button></div></form>`);const f=$('#finance-plan-form'),preview=$('#plan-total-preview');const update=()=>{const o=Object.fromEntries(new FormData(f));const total=financePlanTotal(o);preview.innerHTML=`<b>Total: ${total}%</b><small>${total===100?'✓ Pembagian valid':'Harus tepat 100%'}</small>`;preview.classList.toggle('plan-invalid',total!==100)};f.addEventListener('input',update);f.onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(f));Object.keys(o).forEach(k=>o[k]=Number(o[k]||0));if(!saveFinancePlan(o))return toast('Total persentase harus tepat 100%',true);closeModal();render();toast('Rekomendasi keuangan diperbarui ✓')}}
function financeRecommendation(income,expense){const p=getFinancePlan(),items=[['needs','🏠','Kebutuhan'],['saving','💰','Tabungan'],['investment','📈','Investasi'],['lifestyle','🎉','Lifestyle'],['emergency','🛡️','Dana darurat']];return `<section class="card finance-advice-card"><div class="section-title"><div><h3>🧭 Rekomendasi keuangan</h3><span class="section-hint">Otomatis menyesuaikan dengan pemasukan ${esc(filterLabel())}</span></div><button class="link-btn" data-action="finance-plan-settings">⚙️ Atur persentase</button></div><div class="finance-advice-summary"><div><span>Pemasukan</span><b>${money(income)}</b></div><div><span>Pengeluaran</span><b>${money(expense)}</b></div><div><span>Sisa cashflow</span><b class="${income-expense>=0?'positive':'negative'}">${money(income-expense)}</b></div></div><div class="finance-plan-grid">${items.map(([key,icon,label])=>{const pctv=Number(p[key]||0),amount=income*pctv/100;return `<div class="finance-plan-item"><div class="finance-plan-top"><span>${icon} ${label}</span><b>${pctv}%</b></div><strong>${money(amount)}</strong><div class="finance-plan-bar"><span style="width:${Math.min(100,pctv)}%"></span></div></div>`}).join('')}</div><div class="finance-advice-note">💡 <b>Saran:</b> ${income<=0?'Catat pemasukan terlebih dahulu agar rekomendasi nominal dapat dihitung.':income-expense<0?'Cashflow sedang negatif. Prioritaskan menekan pengeluaran sebelum menaikkan porsi investasi.':`Dengan pola ${p.needs}% kebutuhan, ${p.saving}% tabungan, dan ${p.investment}% investasi, kamu punya kerangka yang jelas untuk mengatur pemasukan.`}</div></section>`}
function advisorData(){const tx=txFiltered(),income=tx.filter(x=>x.type==='income').reduce((a,x)=>a+Number(x.amount),0),expense=tx.filter(x=>x.type==='expense').reduce((a,x)=>a+Number(x.amount),0),saving=income-expense,rate=income?Math.round(saving/income*100):0,cats={};tx.filter(x=>x.type==='expense').forEach(x=>cats[x.category]=(cats[x.category]||0)+Number(x.amount));const top=Object.entries(cats).sort((a,b)=>b[1]-a[1])[0],budget=state.data.budgets.filter(budgetMatches),over=budget.filter(b=>budgetSpent(b)>Number(b.amount||0)).length;return {income,expense,saving,rate,top,budget,over,accounts:state.data.accounts.length,bills:upcomingBills().length,savings:state.data.savings.reduce((a,x)=>a+Number(x.current_amount||0),0),investments:state.data.investments.reduce((a,x)=>a+Number(x.current_value||0),0)}}
function advisorAnswer(q=''){const d=advisorData(),x=q.toLowerCase();if(!d.income)return 'Belum ada pemasukan pada periode ini. Catat pemasukan terlebih dahulu supaya saya bisa memberi saran yang lebih akurat.';if(/budget|anggaran|boros/.test(x))return d.over?`Ada ${d.over} budget yang sudah terlampaui. Fokus pertama: kurangi kategori yang melewati batas, lalu gunakan rekomendasi ${getFinancePlan().needs}% kebutuhan sebagai batas kasar pengeluaran.`:`Budget kamu belum terlampaui pada periode ini. Pertahankan pengeluaran dan sisakan ruang untuk tabungan serta dana darurat.`;if(/tabung|saving|simpan/.test(x))return `Cashflow kamu ${money(d.saving)} dengan saving rate ${d.rate}%. Target awal yang sehat bisa diarahkan ke ${getFinancePlan().saving}% pemasukan, yaitu sekitar ${money(d.income*getFinancePlan().saving/100)} pada periode ini.`;if(/invest|saham|reksa|crypto|emas/.test(x))return `Porsi investasi yang kamu atur saat ini ${getFinancePlan().investment}%, sekitar ${money(d.income*getFinancePlan().investment/100)}. Pastikan dana darurat dan kebutuhan rutin aman sebelum menambah risiko investasi.`;if(/tagihan|bill|listrik|spotify|internet/.test(x))return d.bills?`Ada ${d.bills} tagihan mendatang. Sisihkan nominal tagihan terlebih dahulu agar investasi atau lifestyle tidak memakan uang untuk kewajiban.`:'Belum ada tagihan mendatang yang tercatat.';if(/saldo|akun|cash/.test(x))return `Kamu memiliki ${d.accounts} akun finansial. Total saldo sebaiknya dipandang sebagai buffer kas, sedangkan investasi dan tabungan target dipantau terpisah.`;if(/beli|motor|rumah|mobil|gadget|cicil/.test(x))return `Sebelum membeli, cek apakah setelah pembelian kamu masih bisa memenuhi kebutuhan ${getFinancePlan().needs}%, tabungan ${getFinancePlan().saving}%, dan dana darurat ${getFinancePlan().emergency}%. Jika cashflow tetap positif, risikonya lebih terkendali.`;return `Ringkasnya: pemasukan ${money(d.income)}, pengeluaran ${money(d.expense)}, dan sisa ${money(d.saving)} dengan saving rate ${d.rate}%. Pengeluaran terbesar saat ini ${d.top?d.top[0]:'belum ada'}${d.top?' sebesar '+money(d.top[1]):''}. Saya sarankan menjaga cashflow positif, memenuhi dana darurat, lalu konsisten menabung sebelum mengejar investasi berisiko.`}
function askAdvisor(){const input=$('#advisor-question'),box=$('#advisor-answer');if(!input||!box)return;const q=input.value.trim();box.innerHTML=`<div class="advisor-user">🧑 ${esc(q||'Bagaimana kondisi keuangan saya?')}</div><div class="advisor-ai"><span>🤖</span><div><b>LamTrack AI Advisor</b><p>${esc(advisorAnswer(q))}</p></div></div>`;input.value=''}

function smartForecast(){
  const tx=state.data.transactions||[];
  const monthly={};
  tx.forEach(t=>{
    const k=String(t.date||'').slice(0,7);
    if(!k)return;
    monthly[k]??={income:0,expense:0};
    if(t.type==='income')monthly[k].income+=Number(t.amount||0);
    else monthly[k].expense+=Number(t.amount||0);
  });
  const keys=Object.keys(monthly).sort().slice(-3);
  if(!keys.length)return {avgIncome:0,avgExpense:0,avgCashflow:0,months:0,runway:0};
  const avgIncome=keys.reduce((a,k)=>a+monthly[k].income,0)/keys.length;
  const avgExpense=keys.reduce((a,k)=>a+monthly[k].expense,0)/keys.length;
  const avgCashflow=avgIncome-avgExpense;
  const runway=avgExpense>0?Math.max(0,totalAccountBalance()/avgExpense):0;
  return {avgIncome,avgExpense,avgCashflow,months:keys.length,runway};
}
function smartActions(){
  const d=advisorData(), actions=[];
  if(!d.income)actions.push({icon:'💰',title:'Catat pemasukan',text:'Tambahkan pemasukan agar LamTrack bisa menghitung rasio dan rekomendasi.'});
  if(d.saving<0)actions.push({icon:'🚨',title:'Pulihkan cashflow',text:'Pengeluaran lebih besar dari pemasukan. Tunda pengeluaran non-wajib terlebih dahulu.'});
  if(d.over)actions.push({icon:'🎯',title:'Review budget',text:`${d.over} budget sudah melewati batas. Fokuskan pengurangan pada kategori terbesar.`});
  if(d.income&&d.rate<10)actions.push({icon:'🛡️',title:'Bangun buffer',text:'Saving rate masih rendah. Mulai dari target kecil dan konsisten sebelum menambah risiko investasi.'});
  if(!actions.length)actions.push({icon:'✨',title:'Pertahankan ritme',text:'Cashflow dan budget terlihat terkendali. Jaga konsistensi dan tambah buffer secara bertahap.'});
  return actions.slice(0,3);
}
function smartMoneyCard(){
  const f=smartForecast(),d=advisorData(),score=healthScore(txFiltered(),totalAccountBalance()).score;
  const forecast=f.avgCashflow>=0?`+ ${money(f.avgCashflow)}`:`- ${money(Math.abs(f.avgCashflow))}`;
  const runway=f.runway>=12?'12+ bln':f.runway>=1?`${f.runway.toFixed(1)} bln`:'< 1 bln';
  return `<section class="smart-grid"><section class="card money-momentum-card"><div class="section-title"><div><h3>🚀 Money Momentum</h3><span class="section-hint">Pandangan cepat tentang arah keuanganmu</span></div><span class="momentum-score">${score}/100</span></div><div class="momentum-main"><div><small>Rata-rata cashflow</small><strong class="${f.avgCashflow>=0?'positive':'negative'}">${forecast}</strong><span>${f.months} bulan data terakhir</span></div><div class="momentum-ring" style="--score:${score*3.6}deg"><span>${score}</span></div></div><div class="momentum-meta"><div><span>Rata-rata pemasukan</span><b>${money(f.avgIncome)}</b></div><div><span>Rata-rata pengeluaran</span><b>${money(f.avgExpense)}</b></div><div><span>Perkiraan runway kas</span><b>${runway}</b></div></div></section><section class="card smart-actions-card"><div class="section-title"><div><h3>🧠 Smart checklist</h3><span class="section-hint">Prioritas yang paling relevan saat ini</span></div></div>${smartActions().map(a=>`<div class="smart-action-row"><span>${a.icon}</span><div><b>${a.title}</b><small>${a.text}</small></div></div>`).join('')}</section></section>`;
}

