async function saveRow(table,obj,id,label){
  const form=document.querySelector('#entity-form');
  const submit=form?.querySelector('button[type="submit"]');
  const oldText=submit?.textContent;
  try{
    if(!sb)throw new Error('Supabase belum terhubung.');
    const {data:{session}}=await sb.auth.getSession();
    if(!session?.user)throw new Error('Sesi login sudah berakhir. Silakan login kembali.');
    state.user=session.user;
    obj.user_id=session.user.id;
    if(!obj.created_at) delete obj.created_at;

    if(submit){submit.disabled=true;submit.textContent='Menyimpan...';}

    // Jangan memakai .select() di sini. .insert().select() dapat gagal hanya karena
    // SELECT policy/RLS, padahal INSERT sebenarnya sudah diizinkan.
    let result;
    if(id){
      result=await sb.from(table).update(obj).eq('id',id).eq('user_id',session.user.id);
    }else{
      result=await sb.from(table).insert(obj);
    }
    if(result.error){
      console.error(`[LamTrack] ${table} save error`,result.error,obj);
      throw new Error(result.error.message||result.error.details||'Database error');
    }

    await loadAll();
    closeModal();
    render();
    toast(`${label} berhasil disimpan ✓`);
    return true;
  }catch(err){
    console.error(`[LamTrack] ${table} save exception`,err);
    toast(`Gagal menyimpan ${label}: ${err?.message||err}`,true);
    return false;
  }finally{
    if(submit){submit.disabled=false;submit.textContent=oldText||'Simpan';}
  }
}
