function accountModal(a={}){openModal(a.id?'Edit akun':'Tambah akun',`<form id="entity-form" class="modal-form"><div class="form-grid"><label>Nama akun<input name="name" required value="${esc(a.name)}" placeholder="BCA"></label><label>Tipe<select name="type"><option value="bank" ${a.type==='bank'?'selected':''}>Bank</option><option value="ewallet" ${a.type==='ewallet'?'selected':''}>E-Wallet</option><option value="cash" ${a.type==='cash'?'selected':''}>Cash</option><option value="other" ${a.type==='other'?'selected':''}>Lainnya</option></select></label><label>Saldo awal<input name="balance" type="number" required value="${a.balance??0}"></label><label class="full-col">Catatan<input name="notes" value="${esc(a.notes)}"></label></div><button class="primary full" type="submit">Simpan akun</button></form>`);$('#entity-form').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));o.balance=Number(o.balance);await saveRow('accounts',o,a.id,'Akun')}}
function budgetModal(b={}){openModal(b.id?'Edit budget':'Tambah budget',`<form id="entity-form" class="modal-form"><div class="form-grid"><label>Kategori<select name="category" required>${CATEGORIES.expense.map(c=>`<option value="${esc(c)}" ${b.category===c?'selected':''}>${CAT_ICONS[c]||'📦'} ${esc(c)}</option>`).join('')}</select></label><label>Batas budget<input name="amount" type="number" min="0" required value="${b.amount??''}"></label><label>Periode<select name="frequency" id="budget-frequency">${BUDGET_PERIODS.map(x=>`<option value="${x[0]}" ${b.frequency===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label>Mulai<input name="start_date" type="date" required value="${b.start_date||today()}"></label><label class="full-col" id="budget-end-wrap">Selesai / tanggal akhir<input name="end_date" type="date" value="${b.end_date||''}"></label><label class="full-col">Catatan<input name="notes" value="${esc(b.notes)}" placeholder="Opsional"></label></div><div class="cute-note">🎯 Budget mingguan, bulanan, triwulan, tahunan, atau periode khusus. Setelah migration V6 dijalankan, periode tersimpan lengkap.</div><button class="primary full" type="submit">Simpan budget</button></form>`);$('#entity-form').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));o.amount=Number(o.amount);o.month=String(o.start_date||today()).slice(0,7);await saveRow('budgets',o,b.id,'Budget')}}
function savingModal(s={}){openModal(s.id?'Edit target tabungan':'Tambah target tabungan',`<form id="entity-form" class="modal-form"><div class="form-grid"><label>Nama target<input name="name" required value="${esc(s.name)}" placeholder="Dana Darurat"></label><label>Target nominal<input name="target_amount" type="number" min="0" required value="${s.target_amount??''}"></label><label>Saldo saat ini<input name="current_amount" type="number" min="0" required value="${s.current_amount??0}"></label><label>Deadline<input name="deadline" type="date" value="${s.deadline||''}"></label></div><button class="primary full" type="submit">Simpan target</button></form>`);$('#entity-form').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));o.target_amount=Number(o.target_amount);o.current_amount=Number(o.current_amount);await saveRow('savings',o,s.id,'Target tabungan')}}
function contributionModal(s){
  openModal('Tambah kontribusi',`<form id="entity-form" class="modal-form contribution-modal-form">
    <div class="contribution-hero"><div class="contribution-orb">💚</div><div><span class="eyebrow">SAVING MOMENT</span><h4>Tambah kontribusi</h4><p>Setiap kontribusi kecil membuat targetmu bergerak lebih dekat.</p></div></div>
    <div class="contribution-target"><span>🎯 Target</span><b>${esc(s.name)}</b><small>${money(s.current_amount||0)} dari ${money(s.target_amount||0)}</small><div class="progress"><span style="width:${pct(s.current_amount,s.target_amount)}%"></span></div></div>
    <div class="form-grid"><label>Tanggal<input name="date" type="date" required value="${today()}"></label><label>Nominal kontribusi<input name="amount" type="number" min="1" required placeholder="50000"></label><label class="full-col">Catatan<input name="notes" placeholder="Contoh: Nabung dari gaji"></label></div>
    <div class="contribution-tip">✨ Kontribusi akan masuk ke tracking harian dan otomatis menambah saldo target.</div>
    <div class="modal-submit-bar"><button class="primary full premium-submit" type="submit">+ Simpan kontribusi</button></div>
  </form>`);
  $('#entity-form').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));o.amount=Number(o.amount);o.saving_id=s.id;const ok=await saveRow('saving_contributions',o,null,'Kontribusi');if(ok){const ns=Number(s.current_amount)+o.amount;await sb.from('savings').update({current_amount:ns}).eq('id',s.id);await loadAll();render()}}
}
function investmentModal(i={}){openModal(i.id?'Edit investasi':'Tambah investasi',`<form id="entity-form" class="modal-form"><div class="form-grid"><label>Nama aset<input name="name" required value="${esc(i.name)}" placeholder="BBCA / SBN / Emas"></label><label>Jenis<select name="type">${['Saham','Reksa Dana','Obligasi','Emas','Crypto','Lainnya'].map(x=>`<option ${i.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Modal<input name="capital" type="number" min="0" required value="${i.capital??''}"></label><label>Nilai sekarang<input name="current_value" type="number" min="0" required value="${i.current_value??''}"></label><label class="full-col">Catatan<input name="notes" value="${esc(i.notes)}"></label></div><button class="primary full" type="submit">Simpan investasi</button></form>`);$('#entity-form').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));o.capital=Number(o.capital);o.current_value=Number(o.current_value);await saveRow('investments',o,i.id,'Investasi')}}

const ASSET_TYPES=[
  ['house','🏠','Rumah'],['land','🌳','Tanah'],['car','🚗','Mobil'],['motorcycle','🏍️','Motor'],['property','🏢','Properti'],['gold','🪙','Emas'],['jewelry','💎','Perhiasan'],['electronics','💻','Elektronik'],['other','📦','Lainnya']
];
function assetTypeInfo(type){const hit=ASSET_TYPES.find(x=>x[0]===type)||ASSET_TYPES.at(-1);return {icon:hit[1],label:hit[2]}}
function assetModal(a={}){
  const type=a.type||'house';
  openModal(a.id?'Edit aset':'Tambah aset',`<form id="entity-form" class="modal-form asset-modal-form">
    <div class="asset-modal-intro"><div class="asset-preview-orb">${assetTypeInfo(type).icon}</div><div><b>Bangun portofolio asetmu</b><small>Catat nilai aset nyata di luar saldo dan investasi.</small></div></div>
    <div class="form-grid">
      <label>Nama aset<input name="name" required value="${esc(a.name)}" placeholder="Rumah, Honda Vario, Tanah Samarinda..."></label>
      <label>Jenis aset<select name="type" id="asset-type">${ASSET_TYPES.map(x=>`<option value="${x[0]}" ${type===x[0]?'selected':''}>${x[1]} ${x[2]}</option>`).join('')}</select></label>
      <label>Nilai saat ini<input name="current_value" type="number" min="0" required value="${a.current_value??''}" placeholder="500000000"></label>
      <label>Harga perolehan<input name="purchase_value" type="number" min="0" value="${a.purchase_value??''}" placeholder="450000000"></label>
      <label>Tanggal perolehan<input name="purchase_date" type="date" value="${a.purchase_date||''}"></label>
      <label class="full-col">Catatan<input name="notes" value="${esc(a.notes)}" placeholder="Lokasi, kondisi, cicilan, dokumen, dll."></label>
    </div>
    <div class="asset-modal-note">💡 Nilai aset bisa kamu update kapan saja. LamTrack menggunakannya untuk menghitung total kekayaan aset.</div>
    <button class="primary full premium-submit" type="submit">Simpan aset ✨</button>
  </form>`);
  const typeSelect=$('#asset-type'),orb=document.querySelector('.asset-preview-orb');
  typeSelect?.addEventListener('change',()=>{if(orb)orb.textContent=assetTypeInfo(typeSelect.value).icon});
  $('#entity-form').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));o.current_value=Number(o.current_value||0);o.purchase_value=Number(o.purchase_value||0);o.icon=assetTypeInfo(o.type).icon;await saveRow('assets',o,a.id,'Aset')}
}
function renderAssets(){
  const assets=[...state.data.assets];
  const total=assets.reduce((a,x)=>a+Number(x.current_value||0),0);
  const cost=assets.reduce((a,x)=>a+Number(x.purchase_value||0),0);
  const gain=total-cost;
  const byType={}; assets.forEach(a=>{const k=assetTypeInfo(a.type).label;byType[k]=(byType[k]||0)+Number(a.current_value||0)});
  const top=Object.entries(byType).sort((a,b)=>b[1]-a[1])[0];
  return `<section class="assets-page">
    <div class="assets-hero">
      <div><span class="eyebrow">LAMTRACK ASSET VAULT</span><h1>Asetmu, bukan cuma angka. 🏡</h1><p>Kelola rumah, tanah, mobil, motor, emas, dan aset nyata lainnya dalam satu portofolio visual.</p><div class="hero-actions"><button class="hero-btn" data-action="add-asset">＋ Tambah aset</button><button class="hero-btn ghost" data-page-direct="analytics">📊 Lihat laporan</button></div></div>
      <div class="asset-scene"><span class="asset-animal">🦊</span><span class="scene-item si-house">🏠</span><span class="scene-item si-car">🚗</span><span class="scene-item si-tree">🌳</span><span class="scene-glow"></span></div>
    </div>
    <div class="asset-stat-grid">
      <div class="asset-stat-card"><span>💎</span><small>Total nilai aset</small><strong>${money(total)}</strong><em>${assets.length} aset tercatat</em></div>
      <div class="asset-stat-card"><span>💰</span><small>Total harga perolehan</small><strong>${money(cost)}</strong><em>Modal aset</em></div>
      <div class="asset-stat-card ${gain>=0?'positive':''}"><span>${gain>=0?'📈':'📉'}</span><small>Perubahan nilai</small><strong>${gain>=0?'+':''}${money(gain)}</strong><em>Nilai saat ini − perolehan</em></div>
      <div class="asset-stat-card"><span>🏆</span><small>Aset terbesar</small><strong>${esc(top?.[0]||'-')}</strong><em>${top?money(top[1]):'Belum ada data'}</em></div>
    </div>
    <section class="card asset-portfolio-card"><div class="section-title"><div><h3>🗂️ Portofolio aset</h3><span class="section-hint">Nilai dan detail aset yang kamu miliki</span></div><button class="primary" data-action="add-asset">＋ Tambah</button></div>
    ${assets.length?`<div class="asset-grid">${assets.map(a=>{const inf=assetTypeInfo(a.type),v=Number(a.current_value||0),p=Number(a.purchase_value||0),delta=v-p;return `<article class="asset-card"><div class="asset-card-art"><span>${inf.icon}</span><i></i></div><div class="asset-card-body"><div class="asset-card-top"><div><b>${esc(a.name)}</b><small>${inf.label}</small></div><div class="actions"><button class="small-btn" data-action="edit-asset" data-id="${a.id}">✏️</button><button class="small-btn" data-action="delete-asset" data-id="${a.id}">🗑️</button></div></div><strong class="asset-value">${money(v)}</strong><div class="asset-card-meta"><span>Perolehan ${p?money(p):'-'}</span><span class="${delta>=0?'positive':'negative'}">${delta>=0?'+':''}${money(delta)}</span></div>${a.notes?`<p>${esc(a.notes)}</p>`:''}</div></article>`}).join('')}</div>`:'<div class="asset-empty"><div>🏡</div><h3>Portofoliomu masih kosong</h3><p>Mulai dari rumah, kendaraan, tanah, emas, atau aset lain yang ingin kamu pantau.</p><button class="primary" data-action="add-asset">Tambahkan aset pertama</button></div>'}
    </section>
  </section>`
}

function budgetMatches(b){const start=b.start_date||((b.month||'')+'-01');if(state.filterType==='all')return true;if(state.filterType==='month')return String(start).slice(0,7)===state.filterPeriod;if(state.filterType==='year')return String(start).slice(0,4)===state.filterPeriod;return true}
function billModal(b={}){openModal(b.id?t('editBill'):t('addBill'),`<form id="entity-form" class="modal-form bill-form"><div class="form-grid"><label>${t('billName')}<input name="name" required value="${esc(b.name)}" placeholder="${state.lang==='en'?'Electricity / Spotify / ChatGPT':'Listrik / Spotify / ChatGPT'}"></label><label>${t('provider')}<input name="provider" value="${esc(b.provider)}" placeholder="PLN / Spotify / OpenAI"></label><label>${t('amount')}<input name="amount" type="number" min="0" required value="${b.amount??''}"></label><label>${t('dueDate')}<input name="due_date" type="date" required value="${b.due_date||today()}"></label><label>${t('frequency')}<select name="frequency"><option value="monthly">${t('monthly')}</option><option value="weekly">${t('weekly')}</option><option value="quarterly">${t('quarterly')}</option><option value="yearly">${t('yearly')}</option></select></label><label>Icon<input name="icon" maxlength="4" value="${esc(b.icon||'🧾')}"></label><label class="full-col">${t('notes')}<input name="notes" value="${esc(b.notes)}"></label></div><label class="switch-row"><input type="checkbox" name="is_active" ${b.is_active!==false?'checked':''}> ${t('active')}</label><label class="switch-row"><input type="checkbox" name="autopay" ${b.autopay?'checked':''}> ${t('autopay')}</label><div class="cute-note">💡 ${state.lang==='en'?'This is a bill, not a budget. Use it for recurring payments you actually need to pay.':'Ini adalah tagihan, bukan budget. Gunakan untuk pembayaran rutin yang memang harus dibayar.'}</div><div class="modal-actions"><button class="secondary" type="button" data-close-modal>${t('cancel')}</button><button class="primary" type="submit">${t('save')}</button></div></form>`);const f=$('#entity-form');f.elements.frequency.value=b.frequency||'monthly';f.onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));o.amount=Number(o.amount);o.is_active=f.elements.is_active.checked;o.autopay=f.elements.autopay.checked;await saveRow('bills',o,b.id,'Tagihan')}}
function renderBills(){const bills=state.data.bills.slice().sort((a,b)=>String(a.due_date).localeCompare(String(b.due_date)));return `<div class="page-intro bills-intro"><div><span class="eyebrow">LAMTRACK BILLS</span><h1>${t('upcomingBills')} 🧾</h1><p>${state.lang==='en'?'Keep electricity, subscriptions, internet and other recurring payments under control.':'Pantau listrik, langganan, internet, dan pembayaran rutin lainnya agar tidak tiba-tiba menyergap.'}</p></div><div class="intro-orb">💳</div></div><div class="toolbar"><div class="bill-summary-pills"><span>📌 ${bills.length} ${state.lang==='en'?'active bills':'tagihan tersimpan'}</span><span>💰 ${money(bills.reduce((a,b)=>a+Number(b.amount||0),0))} / periode</span></div><button class="primary" data-action="add-bill">＋ ${t('addBill')}</button></div><section class="card bills-list">${bills.length?bills.map(b=>`<article class="bill-card"><div class="bill-card-icon">${esc(b.icon||'🧾')}</div><div class="bill-card-main"><div class="bill-card-head"><div><h3>${esc(b.name)}</h3><small>${esc(b.provider||'')} · ${billFrequencyLabel(b.frequency)}</small></div><strong>${money(b.amount)}</strong></div><div class="bill-card-meta"><span>📅 ${fmtDate(b.due_date)}</span>${b.autopay?'<span>⚡ Auto bayar</span>':''}${billStatus(b)}</div><p class="muted">${esc(b.notes||'')}</p></div><div class="actions"><button class="small-btn" data-action="edit-bill" data-id="${b.id}">✏️</button><button class="small-btn" data-action="delete-bill" data-id="${b.id}">🗑️</button></div></article>`).join(''):'<div class="empty">Belum ada tagihan. Tambahkan pembayaran rutin pertamamu.</div>'}</section>`}
function renderBudget(){const bs=state.data.budgets.filter(budgetMatches);return `<div class="toolbar"><div><p class="muted">Budget • ${esc(filterLabel())}</p><div class="period-pills">${BUDGET_PERIODS.map(x=>`<span>● ${x[1]}</span>`).join('')}</div></div><button class="primary" data-action="add-budget">+ Tambah budget</button></div><div class="grid-2">${bs.map(b=>{const used=budgetSpent(b);return `<section class="card budget-item"><div class="row-between"><div><b>${CAT_ICONS[b.category]||'📦'} ${esc(b.category)}</b><div class="muted">${esc(b.frequency||'monthly')} · ${esc(b.start_date||b.month||'')}</div></div><div class="actions"><button class="small-btn" data-action="edit-budget" data-id="${b.id}">✏️</button><button class="small-btn" data-action="delete-budget" data-id="${b.id}">🗑️</button></div></div><div class="metric">${money(used)} <span class="muted" style="font-size:13px">/ ${money(b.amount)}</span></div><div class="progress"><span style="width:${pct(used,b.amount)}%"></span></div><small class="muted">${used>b.amount?'⚠️ Melebihi budget':'Tersisa '+money(b.amount-used)}</small></section>`}).join('')||'<div class="card empty">Belum ada budget. Tambahkan budget mingguan sampai tahunan.</div>'}</div>`}
function renderSavings(){const total=state.data.savings.reduce((a,x)=>a+Number(x.current_amount),0),target=state.data.savings.reduce((a,x)=>a+Number(x.target_amount),0),parts=state.data.savings.map((s,i)=>({label:s.name,value:Number(s.current_amount),color:['#5db512','#20a8d8','#ffb84d','#8067d9','#e85d75'][i%5]}));return `<div class="toolbar"><div><p class="muted">Target tabungan pribadi</p><div class="stat-inline"><b>${money(total)}</b> terkumpul dari ${money(target)}</div></div><button class="primary" data-action="add-saving">+ Tambah target</button></div><div class="grid-2"><section class="card"><div class="section-title"><h3>Komposisi dana tabungan</h3></div><div class="pie-layout">${doughnut(parts,total,'Terkumpul')}${pieLegend(parts,total)}</div></section><section class="card"><div class="section-title"><h3>Tracking kontribusi</h3><span class="mini-badge">Harian</span></div>${state.data.saving_contributions.length?state.data.saving_contributions.slice(0,8).map(c=>{const s=state.data.savings.find(x=>x.id===c.saving_id);return `<div class="recent-row"><span class="recent-icon">💚</span><div><b>${esc(s?.name||'Target')}</b><small>${fmtDate(c.date)} · ${esc(c.notes||'Kontribusi')}</small></div><strong class="positive">+ ${money(c.amount)}</strong></div>`}).join(''):'<div class="empty">Belum ada kontribusi.</div>'}</section></div><div class="grid-2 savings-grid">${state.data.savings.map(s=>`<section class="card saving-item"><div class="row-between"><div><h3>${esc(s.name)}</h3><small class="muted">${s.deadline?'Deadline '+fmtDate(s.deadline):'Tanpa deadline'}</small></div><div class="actions"><button class="small-btn" data-action="add-contribution" data-id="${s.id}">＋ Kontribusi</button><button class="small-btn" data-action="edit-saving" data-id="${s.id}">✏️</button><button class="small-btn" data-action="delete-saving" data-id="${s.id}">🗑️</button></div></div><div class="stat-big">${money(s.current_amount)}</div><p class="muted">dari ${money(s.target_amount)}</p><div class="progress"><span style="width:${pct(s.current_amount,s.target_amount)}%"></span></div><p>${pct(s.current_amount,s.target_amount)}% tercapai</p></section>`).join('')||'<div class="card empty">Belum ada target tabungan.</div>'}</div>`}
function renderInvestments(){const total=state.data.investments.reduce((a,x)=>a+Number(x.current_value||0),0),capital=state.data.investments.reduce((a,x)=>a+Number(x.capital||0),0),profit=total-capital,ret=capital?(profit/capital)*100:0;return `<section class="investment-hero"><div><span class="eyebrow">LAMTRACK INVEST</span><h1>Portofolio investasimu 📈</h1><p>Pantau modal, nilai aset, dan perkembangan investasimu dalam satu tampilan.</p></div><div class="investment-hero-orb">💹</div></section><div class="investment-stats"><div class="investment-stat"><span>💼 Nilai investasi</span><strong>${money(total)}</strong><small>Total nilai aset saat ini</small></div><div class="investment-stat"><span>💰 Modal</span><strong>${money(capital)}</strong><small>Total dana yang ditanam</small></div><div class="investment-stat ${profit>=0?'is-positive':'is-negative'}"><span>${profit>=0?'↗':'↘'} Profit / Loss</span><strong>${money(profit)}</strong><small>${ret>=0?'+':''}${ret.toFixed(2)}% return</small></div><div class="investment-stat"><span>🎯 Return</span><strong>${ret.toFixed(2)}%</strong><small>Performa terhadap modal</small></div></div><div class="investment-toolbar"><div><h3>Daftar aset</h3><p class="muted">Kelola investasi yang kamu miliki.</p></div><button class="primary" data-action="add-investment">＋ Tambah investasi</button></div><section class="investment-list">${state.data.investments.length?state.data.investments.map(i=>{const cap=Number(i.capital||0),valx=Number(i.current_value||0),p=valx-cap,r=cap?p/cap*100:0;return `<article class="investment-card"><div class="investment-icon">📈</div><div class="investment-main"><div class="investment-name"><div><b>${esc(i.name)}</b><small>${esc(i.type||'Lainnya')}</small></div><div class="investment-actions"><button class="small-btn" data-action="edit-investment" data-id="${i.id}">✏️</button><button class="small-btn" data-action="delete-investment" data-id="${i.id}">🗑️</button></div></div><div class="investment-values"><div><small>Modal</small><b>${money(cap)}</b></div><div><small>Nilai sekarang</small><b>${money(valx)}</b></div><div class="${p>=0?'positive':'negative'}"><small>P/L</small><b>${p>=0?'+':''}${money(p)}</b></div></div><div class="investment-progress"><div><span>Return</span><b>${r>=0?'+':''}${r.toFixed(2)}%</b></div><div class="progress"><span style="width:${Math.min(100,Math.max(0,50+r/2))}%"></span></div></div></div></article>`}).join(''):'<div class="empty investment-empty">Belum ada investasi. Tambahkan aset pertamamu untuk mulai memantau portofolio.</div>'}</section>`}
function accountTypeInfo(type){
  const map={
    bank:{icon:'🏦',label:state.lang==='en'?'Bank':'Bank',class:'bank'},
    ewallet:{icon:'📱',label:'E-Wallet',class:'ewallet'},
    cash:{icon:'💵',label:state.lang==='en'?'Cash':'Cash',class:'cash'},
    other:{icon:'💼',label:state.lang==='en'?'Other':'Lainnya',class:'other'}
  };
  return map[type]||map.other;
}
function renderAccounts(){
  const accounts=[...state.data.accounts];
  const sort=$('#account-sort')?.value||'default';
  if(sort==='highest')accounts.sort((a,b)=>accountBalance(b)-accountBalance(a));
  if(sort==='used')accounts.sort((a,b)=>{
    const ca=state.data.transactions.filter(t=>String(t.account_id)===String(a.id)).length;
    const cb=state.data.transactions.filter(t=>String(t.account_id)===String(b.id)).length;
    return cb-ca;
  });
  const total=accounts.reduce((a,x)=>a+accountBalance(x),0);
  const usage={};
  state.data.transactions.forEach(t=>{if(t.account_id)usage[t.account_id]=(usage[t.account_id]||0)+1});
  const totalTx=state.data.transactions.filter(t=>t.account_id).length;
  const top=accounts.slice().sort((a,b)=>accountBalance(b)-accountBalance(a))[0];
  const maxBalance=Math.max(...accounts.map(a=>accountBalance(a)),1);
  const maxUsage=Math.max(...accounts.map(a=>usage[a.id]||0),1);
  return `<section class="accounts-page">
    <div class="accounts-hero">
      <div class="accounts-hero-copy">
        <span class="eyebrow">LAMTRACK WALLET</span>
        <h1>${state.lang==='en'?'Your money, beautifully organized.':'Semua uangmu, tertata lebih keren.'}</h1>
        <p>${state.lang==='en'?'See every bank, e-wallet and cash balance at a glance, with activity and usage in one place.':'Pantau saldo bank, e-wallet, dan cash dalam satu layar, lengkap dengan aktivitas dan pemakaiannya.'}</p>
        <div class="accounts-hero-actions"><button class="primary accounts-add-btn" data-action="add-account">＋ ${state.lang==='en'?'Add financial account':'Tambah akun finansial'}</button><button class="secondary accounts-ghost-btn" data-page-direct="transactions">↗ ${state.lang==='en'?'View transactions':'Lihat transaksi'}</button></div>
      </div>
      <div class="accounts-hero-art"><div class="wallet-orb">💳</div><span class="wallet-float f1">💵</span><span class="wallet-float f2">✨</span><span class="wallet-float f3">🪙</span></div>
    </div>

    <div class="account-stat-grid">
      <div class="account-stat-card stat-total"><span>💰</span><div><small>${state.lang==='en'?'Total balance':'Total saldo'}</small><strong>${val(total)}</strong><em>${accounts.length} ${state.lang==='en'?'accounts':'akun'}</em></div></div>
      <div class="account-stat-card"><span>👑</span><div><small>${state.lang==='en'?'Highest balance':'Saldo tertinggi'}</small><strong>${top?val(accountBalance(top)):'Rp 0'}</strong><em>${top?esc(top.name):'-'}</em></div></div>
      <div class="account-stat-card"><span>🔥</span><div><small>${state.lang==='en'?'Activity':'Aktivitas'}</small><strong>${totalTx}</strong><em>${state.lang==='en'?'linked transactions':'transaksi terhubung'}</em></div></div>
      <div class="account-stat-card"><span>🛡️</span><div><small>${state.lang==='en'?'Accounts status':'Status akun'}</small><strong>${accounts.length?state.lang==='en'?'Active':'Aktif':'-'}</strong><em>${state.lang==='en'?'Ready to track':'Siap dipantau'}</em></div></div>
    </div>

    <div class="accounts-toolbar card">
      <div><h3>🏦 ${state.lang==='en'?'Financial accounts':'Akun finansial'}</h3><span class="section-hint">${state.lang==='en'?'Choose a sort order to find your most important account quickly.':'Pilih urutan untuk menemukan akun pentingmu dengan cepat.'}</span></div>
      <select id="account-sort" class="select"><option value="default" ${sort==='default'?'selected':''}>Urutan standar</option><option value="highest" ${sort==='highest'?'selected':''}>💰 ${state.lang==='en'?'Highest balance':'Saldo tertinggi'}</option><option value="used" ${sort==='used'?'selected':''}>🔥 ${state.lang==='en'?'Most used':'Paling sering digunakan'}</option></select>
    </div>

    <section class="accounts-grid">
      ${accounts.length?accounts.map((a,index)=>{
        const bal=accountBalance(a), count=usage[a.id]||0, info=accountTypeInfo(a.type), ratio=Math.min(100,Math.round(bal/maxBalance*100)), activity=Math.min(100,Math.round(count/maxUsage*100));
        const initials=(a.name||'A').trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
        return `<article class="financial-account-card ${info.class}" style="--card-delay:${index*70}ms">
          <div class="account-card-glow"></div>
          <div class="account-card-top"><div class="account-brand-icon">${info.icon}</div><div class="account-card-type"><span>${esc(info.label)}</span><b>${esc(a.name)}</b></div><div class="account-menu-actions"><button class="small-btn" data-action="edit-account" data-id="${a.id}" title="Edit">✏️</button><button class="small-btn" data-action="delete-account" data-id="${a.id}" title="Hapus">🗑️</button></div></div>
          <div class="account-card-number private-value" data-value="${esc(money(bal))}">${val(bal)}</div>
          <div class="account-card-caption">${state.lang==='en'?'Current balance':'Saldo saat ini'}</div>
          <div class="account-meter"><div><span>${state.lang==='en'?'Balance share':'Porsi saldo'}</span><b>${ratio}%</b></div><i><em style="width:${ratio}%"></em></i></div>
          <div class="account-card-footer"><div><small>💳 ${state.lang==='en'?'Activity':'Aktivitas'}</small><b>${count} ${state.lang==='en'?'transactions':'transaksi'}</b></div><div><small>🔐 ${state.lang==='en'?'Status':'Status'}</small><b class="account-active-dot">● ${state.lang==='en'?'Active':'Aktif'}</b></div></div>
          ${a.notes?`<div class="account-note">💬 ${esc(a.notes)}</div>`:''}
        </article>`;
      }).join(''):`<div class="account-empty"><div class="empty-wallet">🏦</div><h3>${state.lang==='en'?'No financial account yet':'Belum ada akun finansial'}</h3><p>${state.lang==='en'?'Add your first bank, e-wallet or cash account to start tracking your balance.':'Tambahkan bank, e-wallet, atau cash pertamamu untuk mulai memantau saldo.'}</p><button class="primary" data-action="add-account">＋ ${state.lang==='en'?'Add account':'Tambah akun'}</button></div>`}
    </section>
  </section>`;
}
 function monthlySeries(){const labels=[],income=[],expense=[],saving=[];for(let i=11;i>=0;i--){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const key=d.toISOString().slice(0,7);labels.push(d.toLocaleDateString('id-ID',{month:'short'}));const tx=state.data.transactions.filter(t=>String(t.date).slice(0,7)===key);const inc=tx.filter(t=>t.type==='income').reduce((a,x)=>a+Number(x.amount),0),exp=tx.filter(t=>t.type==='expense').reduce((a,x)=>a+Number(x.amount),0);income.push(inc);expense.push(exp);saving.push(inc-exp)}return{labels,income,expense,saving}}
function lineChart(s){const W=900,H=300,P=45,max=Math.max(...s.income,...s.expense,...s.saving,1);const path=a=>a.map((v,i)=>`${P+i*(W-2*P)/(a.length-1)},${H-P-(v/max)*(H-2*P)}`).join(' ');return `<div class="legend"><span><i class="dot income"></i>Income</span><span><i class="dot expense"></i>Expense</span><span><i class="dot saving"></i>Saving</span></div><div class="chart-wrap"><svg viewBox="0 0 ${W} ${H}"><line x1="${P}" y1="${H-P}" x2="${W-P}" y2="${H-P}" class="axis"/><polyline points="${path(s.income)}" class="line income"/><polyline points="${path(s.expense)}" class="line expense"/><polyline points="${path(s.saving)}" class="line saving"/>${s.labels.map((l,i)=>`<text x="${P+i*(W-2*P)/(s.labels.length-1)}" y="${H-10}" text-anchor="middle">${l}</text>`).join('')}</svg></div>`}
function financialEvaluation(tx){const inc=tx.filter(t=>t.type==='income').reduce((a,x)=>a+Number(x.amount),0),exp=tx.filter(t=>t.type==='expense').reduce((a,x)=>a+Number(x.amount),0),save=inc-exp,rate=inc?save/inc*100:0;const budgets=state.data.budgets.filter(budgetMatches);const over=budgets.filter(b=>budgetSpent(b)>Number(b.amount||0)).length;const top=Object.entries(tx.filter(t=>t.type==='expense').reduce((o,t)=>(o[t.category]=(o[t.category]||0)+Number(t.amount),o),{})).sort((a,b)=>b[1]-a[1])[0];let text;if(!inc&& !exp)text=state.lang==='en'?'There is not enough transaction data for a meaningful evaluation yet.':'Belum cukup transaksi untuk membuat evaluasi yang berarti.';else if(rate>=30&&over===0)text=state.lang==='en'?`Excellent. Your saving rate is ${Math.round(rate)}% and no tracked budget is over limit. Keep the discipline.`:`Bagus. Saving rate kamu ${Math.round(rate)}% dan tidak ada budget yang terlampaui. Pertahankan disiplin ini.`;else if(rate>=10)text=state.lang==='en'?`Your cashflow is positive at ${money(save)}. Focus on ${top?esc(top[0]):'your biggest category'} and watch ${over} budget(s) that need attention.`:`Cashflow kamu positif ${money(save)}. Fokus pada ${top?esc(top[0]):'kategori terbesar'} dan perhatikan ${over} budget yang perlu diawasi.`;else text=state.lang==='en'?'Spending is consuming most of your income. Reduce discretionary spending and rebuild your saving buffer.':'Pengeluaran sudah memakan sebagian besar pemasukan. Kurangi belanja yang tidak wajib dan bangun kembali buffer tabungan.';return {inc,exp,save,rate,over,top,text}}
function analyticsAIInsight({income,expense,ev,top,budgetRows}){
  const notes=[];
  const cash=income-expense;
  if(!income) notes.push('Belum ada pemasukan pada periode ini. Catat pemasukan agar rasio saving dan rekomendasi menjadi lebih akurat.');
  else if(cash<0) notes.push(`Cashflow negatif ${money(Math.abs(cash))}. Prioritas pertama adalah menekan pengeluaran non-wajib sebelum menambah investasi.`);
  else notes.push(`Cashflow positif ${money(cash)}. Pertahankan surplus dan arahkan sebagian ke tabungan atau dana darurat.`);
  if(ev.rate<10&&income) notes.push(`Saving rate ${Math.round(ev.rate)}% masih rendah. Target awal 10% dapat dijadikan pijakan yang realistis.`);
  else if(ev.rate>=20) notes.push(`Saving rate ${Math.round(ev.rate)}% tergolong kuat. Konsistensi menjadi keunggulan utama saat ini.`);
  if(ev.over) notes.push(`${ev.over} budget melewati batas. ${top?`Kategori terbesar saat ini ${top.label}.`:''} Review transaksi berulang pada kategori tersebut.`);
  if(budgetRows.length&&!ev.over) notes.push('Belum ada budget yang melewati batas. Pertahankan disiplin dan cek budget sebelum pengeluaran besar.');
  return notes.slice(0,4);
}
function renderAnalytics(){
  const tx=txFiltered(),income=tx.filter(t=>t.type==='income').reduce((a,x)=>a+Number(x.amount),0),expense=tx.filter(t=>t.type==='expense').reduce((a,x)=>a+Number(x.amount),0),cats={};
  tx.filter(t=>t.type==='expense').forEach(t=>cats[t.category]=(cats[t.category]||0)+Number(t.amount));
  const parts=Object.entries(cats).sort((a,b)=>b[1]-a[1]).slice(0,8).map((x,i)=>({label:x[0],value:x[1],color:['#5db512','#20a8d8','#ffb84d','#e85d75','#8067d9','#27b59d','#f08a3c','#9b6bff'][i]}));
  const series=monthlySeries(),days=bars7(tx),top=parts[0],ev=financialEvaluation(tx);
  const budgetRows=state.data.budgets.map(b=>({b,used:budgetSpent(b),pct:Number(b.amount)?budgetSpent(b)/Number(b.amount)*100:0})).sort((a,b)=>b.pct-a.pct);
  const budgetOver=budgetRows.filter(x=>x.pct>100).length,budgetNear=budgetRows.filter(x=>x.pct>=80&&x.pct<=100).length;
  const insights=analyticsAIInsight({income,expense,ev,top,budgetRows});
  return `<section class="analytics-page">
  <div class="analytics-hero analytics-premium"><div><span class="eyebrow">LAMTRACK INSIGHT</span><h1>Keuanganmu, dijelaskan dengan jelas.</h1><p>Grafik, pola pengeluaran, performa budgeting, dan insight otomatis dalam satu laporan.</p><div class="hero-actions"><button class="hero-btn" data-action="export-pdf">📄 ${t('exportPdf')}</button></div></div><div class="hero-mascot analytics-animal">🦊</div></div>
  <section class="stat-grid"><div class="stat-card gradient-income"><span>Income</span><strong>${money(income)}</strong><small>Periode terpilih</small></div><div class="stat-card gradient-expense"><span>Expense</span><strong>${money(expense)}</strong><small>Periode terpilih</small></div><div class="stat-card gradient-save"><span>Saving</span><strong>${money(income-expense)}</strong><small>Cashflow bersih</small></div><div class="stat-card gradient-invest"><span>Top kategori</span><strong>${esc(top?.label||'-')}</strong><small>${top?money(top.value):'Belum ada data'}</small></div></section>
  <section class="card ai-report-card"><div class="section-title"><div><h3>🤖 LamTrack AI Insight</h3><span class="section-hint">Resume otomatis dari data laporan periode ini</span></div><span class="ai-insight-badge">SMART SUMMARY</span></div><div class="ai-report-grid">${insights.map((x,i)=>`<div class="ai-report-item"><span>${['💡','🎯','🛡️','📈'][i]||'✨'}</span><p>${esc(x)}</p></div>`).join('')}</div></section>
  <section class="card report-evaluation"><div class="section-title"><div><h3>🧠 ${t('financialEvaluation')}</h3><span class="section-hint">Evaluasi otomatis dari periode yang dipilih</span></div><span class="evaluation-score">${Math.max(0,Math.min(100,Math.round(ev.rate*1.5+40-ev.over*8)))}/100</span></div><div class="evaluation-grid"><div><b>💚 Saving rate</b><strong>${Math.round(ev.rate)}%</strong></div><div><b>💸 Cashflow</b><strong>${money(ev.save)}</strong></div><div><b>🎯 Budget over</b><strong>${ev.over}</strong></div></div><div class="evaluation-text">${ev.text}</div></section>
  <section class="card budget-performance-report"><div class="section-title"><div><h3>🎯 Performa budgeting</h3><span class="section-hint">Budget vs realisasi, termasuk peringatan sebelum over</span></div><div class="budget-report-badges"><span>${budgetRows.length} budget</span><span>${budgetNear} mendekati</span><span class="${budgetOver?'danger':''}">${budgetOver} over</span></div></div>${budgetRows.length?`<div class="budget-report-list">${budgetRows.map(x=>{const p=x.pct,cls=p>100?'over':p>=80?'near':'safe';return `<div class="budget-report-row"><div class="budget-report-head"><div><b>${CAT_ICONS[x.b.category]||'🎯'} ${esc(x.b.category)}</b><small>${money(x.used)} / ${money(x.b.amount)}</small></div><strong class="${cls}">${Math.round(p)}%</strong></div><div class="budget-report-track"><span class="${cls}" style="width:${Math.min(100,p)}%"></span></div><small class="budget-report-status">${p>100?'⚠️ Melebihi batas':p>=80?'🟡 Sudah mendekati batas':'🟢 Masih terkendali'}</small></div>`}).join('')}</div>`:'<div class="empty">Belum ada budget pada periode ini.</div>'}</section>
  <section class="card"><div class="section-title"><div><h3>📈 Performa bulanan</h3><span class="section-hint">Income · Expense · Saving · 12 bulan terakhir</span></div></div>${lineChart(series)}</section>
  <div class="grid-2"><section class="card"><div class="section-title"><h3>🎨 Distribusi pengeluaran</h3></div><div class="pie-layout">${doughnut(parts,expense,'Total')}${pieLegend(parts,expense)}</div></section><section class="card"><div class="section-title"><h3>🔥 Pola pengeluaran</h3></div>${days}</section></div>
  </section>`
}

